---RefreshUI
---@param suitData table {suitId, name, desc, iconPath}
---@param ownEquipPartMap table<number, number>
function UICultivateEquipSuitInfoExpandNode:RefreshUI(suitData, ownEquipPartMap, showType, position, selectPart)
    local data  = ownEquipPartMap
    local count = 0
    local part2Count = {}
    if showType == 1 then
        count = #data
    else
        for part, ids in pairs(ownEquipPartMap) do
            local partCount = #ids
            part2Count[part] = partCount
            count = partCount + count
        end
    end

    self.NameText.text = suitData.name
    self.SuitIcon:LoadSprite(suitData.iconPath)
    self.SuitDescText.text = suitData.desc
    self.OwnNumText.text = string.format("x%s", count)

    local occupationId = suitData.occupationId
    local isShowEquipCoreTypeIcon = occupationId > 0
    KTool.SetActive(self.TypeNode.gameObject, isShowEquipCoreTypeIcon)
    if isShowEquipCoreTypeIcon then
        self:RefreshCoreType(occupationId)
    end

    local corePartCount = part2Count[-1] or 0

    self:RefreshMarkNode(self.Core, -1, selectPart, corePartCount)
    for i = 1, Constants.CardEquipmentNo do
        local partCount = part2Count[i] or 0
        self:RefreshMarkNode(self[string.format("Mark%s", i)], i, selectPart, partCount)
    end

    self.position = position
    self.count = count

    self.Background.alpha = count > 0 and 1 or 0.5

    CS.UnityEngine.UI.LayoutRebuilder.ForceRebuildLayoutImmediate(self.InfoExpandNode)
end

function UICultivateEquipSuitInfoExpandNode:RefreshMarkNode(node, part, selectPart, ownNum)
    ---@type UICultivateEquipSuitMarkNode
    local env = CfUtils.GetLuaScr(node, MarkNodeEnvPath)
    if isNull(env) then
        return
    end
    env:RefreshUI(part, selectPart, ownNum)
end

function UICultivateEquipSuitInfoExpandNode:ShowAnimate(index)
    ---------------------------
    --- 动画初始设置
    ---@type UnityEngine.Transform
    local containerTrans = self.Container.transform
    local canvasGroup = self.Container
    canvasGroup.alpha = 0

    local localPosition = containerTrans.localPosition
    containerTrans.localPosition = Vector3.New(localPosition.x, localPosition.y - 45, localPosition.z)

    ---------------------------
    --- 播放动画
    local sequence = DOTween:Sequence()
    local moveAni  = containerTrans:DOLocalMoveY(localPosition.y, AniTime):SetDelay(AniDelayTime * index)
    local fadeAni  = canvasGroup:DOFade(1, AniTime):SetDelay(AniDelayTime * index)
    sequence:Append(moveAni)
    sequence:Join(fadeAni)
end

---RefreshCoreType
---@param occupationId number   职业id
function UICultivateEquipSuitInfoExpandNode:RefreshCoreType(occupationId)
    ---@type UICultivateCareerTypeNode
    local mbEnv = CfUtils.GetLuaScr(self.CareerTypeNode.gameObject, UICultivateCareerTypeNodePath)
    if mbEnv == nil then
        return
    end

    mbEnv:RefreshUI(occupationId)
end

